n=30
g=[[0]*n for _ in range(n)]
# Preserve the 5-frame spanning rows/cols 1..25; fill its interior with the demonstrated two nested rings.
for r in range(1,26):
    for c in range(1,26):
        if r in (1,25) or c in (1,25):
            g[r][c]=5
        else:
            d=min(r-2,24-r,c-2,24-c)
            g[r][c]=2 if d==0 else 5 if d==1 else 0
import json
print(json.dumps(g,separators=(',',':')))
